    const el = event?.target;
    if (el === null || typeof el?.matches !== 'function' || !el.matches(COMPOSER_SELECTOR)) return;
    if (state.el !== el) {
      pendingUp = 0;
      fetchSeq += 1;
      state.el = el;
      state.index = -1;
      state.entry = '';
      state.list = null;
      state.sessionId = '';
      state.shell = null;
    }
